def solve(payload):
    events = payload["events"]
    if payload["slow_after_s"] < 0:
        return {"error": "invalid_policy"}
    if any(e["kind"] not in ("open", "close") for e in events):
        return {"error": "invalid_kind"}
    if any(e["time_s"] < 0 or (i and e["time_s"] < events[i-1]["time_s"]) for i, e in enumerate(events)):
        return {"error": "time_order"}
    active, completed, anomalies = {}, [], []
    for index, event in enumerate(events):
        key, now = event["id"], event["time_s"]
        if event["kind"] == "open":
            if key in active:
                anomalies.append({"index": index, "id": key, "code": "duplicate_open"})
            else:
                active[key] = now
        elif key not in active:
            anomalies.append({"index": index, "id": key, "code": "unmatched_close"})
        else:
            duration = now-active.pop(key)
            completed.append({"id": key, "duration_s": duration, "slow": duration > payload["slow_after_s"]})
    return {"completed": completed, "anomalies": anomalies, "pending": sorted(active)}

